#[test]
fn test_find_count_lists_all_documents() {
    let dir = setup_workspace();

    write(dir.path().join("doc1.md"), "# Document One\n\nContent one.").unwrap();
    write(dir.path().join("doc2.md"), "# Document Two\n\nContent two.").unwrap();
    write(dir.path().join("doc3.md"), "# Document Three\n\nContent three.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "3");
}

#[test]
fn test_find_count_with_query() {
    let dir = setup_workspace();

    write(dir.path().join("authentication.md"), "# Authentication\n\nContent.").unwrap();
    write(dir.path().join("database.md"), "# Database\n\nContent.").unwrap();
    write(dir.path().join("api.md"), "# API\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["auth", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "1");
}

#[test]
fn test_find_count_with_roots_filter() {
    let dir = setup_workspace();

    write(
        dir.path().join("parent.md"),
        indoc! {"
            # Parent

            [child](child)
        "},
    )
    .unwrap();

    write(dir.path().join("child.md"), "# Child\n\nChild content.").unwrap();
    write(dir.path().join("orphan.md"), "# Orphan\n\nNo references.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--roots", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
}

#[test]
fn test_find_count_with_refs_to_filter() {
    let dir = setup_workspace();

    write(
        dir.path().join("doc1.md"),
        indoc! {"
            # Doc One

            [target](target)
        "},
    )
    .unwrap();

    write(
        dir.path().join("doc2.md"),
        indoc! {"
            # Doc Two

            [target](target)
        "},
    )
    .unwrap();

    write(dir.path().join("doc3.md"), "# Doc Three\n\nNo refs.").unwrap();
    write(dir.path().join("target.md"), "# Target\n\nTarget content.").unwrap();

    let (stdout, stderr, success) =
        run_iwe(dir.path(), &["--refs-to", "target", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
}

#[test]
fn test_find_count_with_no_matches() {
    let dir = setup_workspace();

    write(dir.path().join("document.md"), "# My Document\n\nContent.").unwrap();

    let (stdout, stderr, success) =
        run_iwe(dir.path(), &["zzzznonexistent", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "0");
}

#[test]
fn test_find_count_empty_workspace() {
    let dir = setup_workspace();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "0");
}

#[test]
fn test_find_count_overrides_format() {
    let dir = setup_workspace();

    write(dir.path().join("doc1.md"), "# Document One\n\nContent.").unwrap();
    write(dir.path().join("doc2.md"), "# Document Two\n\nContent.").unwrap();

    let (stdout, stderr, success) =
        run_iwe(dir.path(), &["--count", "-f", "json"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
    assert!(!stdout.contains("results"));
    assert!(!stdout.contains("{"));
}
